class SimulatedTransaction {
    private final List<String> log = new ArrayList<>();
    void commit() { System.out.println("COMMIT: " + log); }
    void record(String operation) { log.add(operation); }
}

class PlaceOrderUseCase {
    boolean placeOrder(String orderId, int quantity) {
        SimulatedTransaction transaction = new SimulatedTransaction();
        transaction.record("reserveStock(" + quantity + ")");
        transaction.record("save(" + orderId + ")");
        transaction.commit(); // JEDYNE miejsce, gdzie granica transakcji sie zaczyna i konczy
        return true;
    }
}

// ZLE: kazda metoda repozytorium commituje SAMODZIELNIE - brak wspolnej granicy
class AutoCommittingOrderRepository {
    void reserveStock(int quantity) {
        System.out.println("Rezerwacja magazynu: " + quantity);
        System.out.println("COMMIT (osobno!)"); // <- juz zapisane, nieodwracalnie
    }
    void save(String orderId) {
        throw new RuntimeException("Blad zapisu zamowienia"); // <- to sie NIE UDAJE
        // rezerwacja magazynu JUZ jest zacommitowana - dane sa NIESPOJNE
    }
}

// ZLE: kontroler sam zarzadza transakcja obejmujaca NIEPOWIAZANE operacje
class OrderControllerWithTransaction {
    String handleHttpRequest(String orderId, int quantity) {
        SimulatedTransaction transaction = new SimulatedTransaction();
        orderService.placeOrder(orderId, quantity);       // przypadek uzycia 1
        analyticsService.recordPageView("order-page");     // NIEPOWIAZANY przypadek uzycia 2
        transaction.commit(); // oba "zwiazane" jedna transakcja - bez sensu biznesowego
        return "200 OK";
    }
}

